ComfyPanel=ComfyPanel or {}
local A=ComfyPanel
local function FreeSlots() local t=0 for bag=0,4 do local v if C_Container and type(C_Container.GetContainerNumFreeSlots)=="function" then local ok,x=pcall(C_Container.GetContainerNumFreeSlots,bag); if ok then v=x end elseif type(GetContainerNumFreeSlots)=="function" then local ok,x=pcall(GetContainerNumFreeSlots,bag); if ok then v=x end end t=t+(tonumber(v) or 0) end return t end
local function Money() local c=type(GetMoney)=="function" and tonumber(GetMoney()) or 0 if type(GetMoneyString)=="function" then local ok,v=pcall(GetMoneyString,c,true); if ok and v then return v end end return tostring(c or 0) end
function A:CreatePanel() if self.panelFrame then return end local f=CreateFrame("Frame","ComfyPanelBar",UIParent,"BackdropTemplate"); f:SetFrameStrata("BACKGROUND"); f:SetBackdrop({bgFile="Interface\\Buttons\\WHITE8X8"}); f.left=f:CreateFontString(nil,"OVERLAY","GameFontHighlightSmall"); f.left:SetPoint("LEFT",8,0); f.right=f:CreateFontString(nil,"OVERLAY","GameFontHighlightSmall"); f.right:SetPoint("RIGHT",-8,0); self.panelFrame=f end
function A:RefreshFeature() self:CreatePanel(); local f=self.panelFrame; local c=self.db and self.db.panel; if not c or not self.db.enabled then f:Hide(); return end local edge=c.position=="BOTTOM" and "BOTTOM" or "TOP"; f:ClearAllPoints(); f:SetPoint(edge,UIParent,edge); f:SetWidth(UIParent:GetWidth() or 1024); f:SetHeight(tonumber(c.height) or 22); f:SetBackdropColor(0.025,0.025,0.03,(tonumber(c.opacity) or 85)/100); local l,r={},{}; if c.showMoney then l[#l+1]="Gold: "..Money() end; if c.showBags then l[#l+1]="Bags: "..FreeSlots().." free" end; if c.showTime then r[#r+1]=(date and date("%H:%M") or "--:--") end; if c.showFPS and type(GetFramerate)=="function" then r[#r+1]=string.format("FPS %.0f",tonumber(GetFramerate()) or 0) end; if c.showLatency and type(GetNetStats)=="function" then local ok,_,_,h,w=pcall(GetNetStats); if ok then r[#r+1]=string.format("MS %d/%d",tonumber(h) or 0,tonumber(w) or 0) end end; f.left:SetText(table.concat(l,"  |  ")); f.right:SetText(table.concat(r,"  |  ")); f:Show() end
function A:InitializeFeature() self:CreatePanel(); local e=CreateFrame("Frame"); for _,ev in ipairs({"PLAYER_MONEY","BAG_UPDATE_DELAYED","PLAYER_ENTERING_WORLD"}) do pcall(e.RegisterEvent,e,ev) end; e:SetScript("OnEvent",function() A:RefreshFeature() end); e:SetScript("OnUpdate",function(self,dt) self.t=(self.t or 0)+(tonumber(dt) or 0); if self.t>=1 then self.t=0; A:RefreshFeature() end end) end
function A:BuildGeneralOptions(page,ui) ui.CreateDropdown(page,5,-85,180,function() return {{value="TOP",text=A:T("TOP")},{value="BOTTOM",text=A:T("BOTTOM")}} end,function() return A.db.panel.position end,function(v) A.db.panel.position=v end); ui.CreateCheck(page,A:T("SHOW_MONEY"),20,-135,function() return A.db.panel.showMoney end,function(v) A.db.panel.showMoney=v end); ui.CreateCheck(page,A:T("SHOW_BAGS"),20,-170,function() return A.db.panel.showBags end,function(v) A.db.panel.showBags=v end); ui.CreateCheck(page,A:T("SHOW_TIME"),20,-205,function() return A.db.panel.showTime end,function(v) A.db.panel.showTime=v end); ui.CreateCheck(page,A:T("SHOW_FPS"),20,-240,function() return A.db.panel.showFPS end,function(v) A.db.panel.showFPS=v end); ui.CreateCheck(page,A:T("SHOW_LATENCY"),20,-275,function() return A.db.panel.showLatency end,function(v) A.db.panel.showLatency=v end); ui.CreateSlider(page,A:T("HEIGHT"),16,36,1,360,-135,function() return A.db.panel.height end,function(v) A.db.panel.height=math.floor(v+0.5) end,function(v) return math.floor(v+0.5).." px" end); ui.CreateSlider(page,A:T("OPACITY"),20,100,5,360,-220,function() return A.db.panel.opacity end,function(v) A.db.panel.opacity=math.floor(v+0.5) end,function(v) return math.floor(v+0.5).."%" end); local n=page:CreateFontString(nil,"ARTWORK","GameFontHighlightSmall"); n:SetPoint("TOPLEFT",20,-360); n:SetWidth(680); n:SetJustifyH("LEFT"); n:SetText(A:T("FOREVER_NOTE")) end
